参考代码（vector邻接表建图）：

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<vector<int>> g(n + 1);
    for (int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        g[u].push_back(v);
        g[v].push_back(u);
    }
    for (int i = 1; i <= n; i++)
        cout << g[i].size() << " \n"[i == n];
    return 0;
}
```

**原理说明**：用vector存无向图邻接表，顶点i的度数即g[i]的长度（`.size()`）。读边时两端各push一次。复杂度O(n+m)。

参考代码（vector邻接表建图）：

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<vector<int>> g(n + 1);
    for (int i = 0; i < m; i++) {
        int a, b;
        cin >> a >> b;
        g[a].push_back(b);
        g[b].push_back(a);
    }
    int u, v;
    cin >> u >> v;
    for (int x : g[u]) {
        if (x == v) {
            cout << "Yes\n";
            return 0;
        }
    }
    cout << "No\n";
    return 0;
}
```

**原理说明**：用vector存无向图邻接表。查询(u,v)时遍历g[u]看v是否在其中。复杂度O(deg(u))。
